--[[
  NIGHTDLC · packed build
  Allowed: Velocity / Potassium only
]]

do
	local ALLOWED = { velocity = true, potassium = true }
	local function detect()
		local name, ver = "Unknown", ""
		local ok, a, b = pcall(function()
			if type(identifyexecutor) == "function" then return identifyexecutor() end
			if type(getexecutorname) == "function" then return getexecutorname() end
		end)
		if ok then
			if type(a) == "string" and a ~= "" then name = a end
			if type(b) == "string" and b ~= "" then ver = b end
		end
		return name, ver
	end
	local name, ver = detect()
	local keyn = string.lower(name):gsub("%s+", "")
	local ok_exec = false
	for k in pairs(ALLOWED) do
		if keyn:find(k, 1, true) then ok_exec = true break end
	end
	getgenv().NIGHTDLC_EXECUTOR = name
	getgenv().NIGHTDLC_EXECUTOR_VER = ver
	if not ok_exec then
		pcall(function()
			local lp = game:GetService("Players").LocalPlayer
			local pg = lp and lp:FindFirstChildOfClass("PlayerGui")
			if not pg then return end
			local g = Instance.new("ScreenGui")
			g.Name = "NIGHTDLC_Blocked"
			g.ResetOnSpawn = false
			g.IgnoreGuiInset = true
			g.DisplayOrder = 99999
			g.Parent = pg
			local f = Instance.new("Frame")
			f.Size = UDim2.fromOffset(360, 120)
			f.Position = UDim2.new(0.5, -180, 0.5, -60)
			f.BackgroundColor3 = Color3.fromRGB(12, 14, 20)
			f.BorderSizePixel = 0
			f.Parent = g
			Instance.new("UICorner", f).CornerRadius = UDim.new(0, 10)
			local s = Instance.new("UIStroke")
			s.Color = Color3.fromRGB(255, 90, 110)
			s.Thickness = 1.5
			s.Parent = f
			local t = Instance.new("TextLabel")
			t.Size = UDim2.new(1, -20, 1, -20)
			t.Position = UDim2.fromOffset(10, 10)
			t.BackgroundTransparency = 1
			t.TextWrapped = true
			t.Font = Enum.Font.GothamBold
			t.TextSize = 14
			t.TextColor3 = Color3.fromRGB(255, 220, 230)
			t.Text = "NIGHTDLC blocked\nOnly Velocity / Potassium\nDetected: " .. name
			t.Parent = f
		end)
		warn("[NIGHTDLC] Blocked executor: " .. name)
		return
	end
	print("[NIGHTDLC] Executor OK: " .. name .. (ver ~= "" and (" " .. ver) or ""))
end

local function _ndlc_decode(payload, key)
	local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	payload = payload:gsub("[^"..alphabet.."=]", "")
	local data = {}
	local build = {}
	local function push(n)
		table.insert(build, string.char(n))
		if #build >= 4096 then
			table.insert(data, table.concat(build))
			build = {}
		end
	end
	for i = 1, #payload, 4 do
		local a = alphabet:find(payload:sub(i, i), 1, true) or 1
		local b = alphabet:find(payload:sub(i+1, i+1), 1, true) or 1
		local c = alphabet:find(payload:sub(i+2, i+2), 1, true) or 1
		local d = alphabet:find(payload:sub(i+3, i+3), 1, true) or 1
		a, b, c, d = a - 1, b - 1, c - 1, d - 1
		local n = a * 262144 + b * 4096 + c * 64 + d
		push(math.floor(n / 65536) % 256)
		if payload:sub(i+2, i+2) ~= "=" then push(math.floor(n / 256) % 256) end
		if payload:sub(i+3, i+3) ~= "=" then push(n % 256) end
	end
	if #build > 0 then table.insert(data, table.concat(build)) end
	local raw = table.concat(data)
	local out = {}
	local chunk = {}
	local klen = #key
	for i = 1, #raw do
		local byte = string.byte(raw, i)
		local kb = key[((i - 1) % klen) + 1]
		local x = byte
		local y = kb
		local r, p2 = 0, 1
		while x > 0 or y > 0 do
			local xb, yb = x % 2, y % 2
			if xb ~= yb then r = r + p2 end
			x, y, p2 = (x - xb) / 2, (y - yb) / 2, p2 * 2
		end
		table.insert(chunk, string.char(r))
		if #chunk >= 4096 then
			table.insert(out, table.concat(chunk))
			chunk = {}
		end
	end
	if #chunk > 0 then table.insert(out, table.concat(chunk)) end
	return table.concat(out)
end

local _KEY = {97,148,120,212,69,60,204,21,124,92,93,132,135,204,208,39,94,47,184,155,146,102,163,151,219,39,154,227,72,13,150,110}
local _PAYLOAD = [==[]==]

local src = _ndlc_decode(_PAYLOAD, _KEY)
local fn, err = loadstring(src)
if not fn then
	warn("[NIGHTDLC] unpack failed: " .. tostring(err))
	return
end
fn()
